+const ANSWERS = {
+  q1: ["js", "py"],     // interpreted languages
+  q2: ["c", "cpp"],     // statically typed & compiled (originally)
+  q3: ["html", "css"],  // markup / styling, not programming languages
+};
+
+document.addEventListener("DOMContentLoaded", () => {
+  // Sync checkbox state → option highlight
+  document.querySelectorAll('.option input[type="checkbox"]').forEach((cb) => {
+    cb.addEventListener("change", () => {
+      cb.closest(".option").classList.toggle("selected", cb.checked);
+    });
+  });
+
+  // Allow clicking anywhere on the option row to toggle the checkbox
+  document.querySelectorAll(".option").forEach((opt) => {
+    opt.addEventListener("click", (e) => {
+      if (e.target.tagName !== "INPUT") {
+        const cb = opt.querySelector('input[type="checkbox"]');
+        cb.checked = !cb.checked;
+        cb.dispatchEvent(new Event("change"));
+      }
+    });
+  });
+
+  document.getElementById("quiz-form").addEventListener("submit", (e) => {
+    e.preventDefault();
+
+    let score = 0;
+
+    Object.entries(ANSWERS).forEach(([name, correct]) => {
+      const checked = Array.from(
+        document.querySelectorAll(`input[name="${name}"]:checked`)
+      ).map((cb) => cb.value);
+
+      const isCorrect =
+        checked.length === correct.length &&
+        correct.every((v) => checked.includes(v));
+
+      if (isCorrect) score++;
+    });
+
+    const banner = document.getElementById("result-banner");
+    const bannerTitle = document.getElementById("result-title");
+    const bannerBody = document.getElementById("result-body");
+
+    const total = Object.keys(ANSWERS).length;
+
+    if (score === total) {
+      banner.className = "result-banner show pass";
+      bannerTitle.textContent = "Perfect score! 🎉";
+      bannerBody.textContent = `You answered all ${total} questions correctly.`;
+    } else {
+      banner.className = "result-banner show fail";
+      bannerTitle.textContent = `${score} of ${total} correct`;
+      bannerBody.textContent =
+        "Review your answers — some selections were incomplete or incorrect.";
+    }
+
+    banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
+  });
+});
+
